import{_ as r,o as a,c as i,a2 as t}from"./chunks/framework.DaGSOal_.js";const f=JSON.parse('{"title":"Discord Verification","description":"How to verify a purchase for a product-specific Discord role.","frontmatter":{"title":"Discord Verification","description":"How to verify a purchase for a product-specific Discord role."},"headers":[],"relativePath":"verification.md","filePath":"verification.md","lastUpdated":1794046641000}'),o={name:"verification.md"};function n(c,e,s,l,d,h){return a(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="discord-verification" tabindex="-1">Discord Verification <a class="header-anchor" href="#discord-verification" aria-label="Permalink to &quot;Discord Verification&quot;">​</a></h1><p>Some Deblx product-specific Discord channels may require purchase verification. Follow the current verification instructions in the <a href="https://discord-dev.deblx.com" target="_blank" rel="noreferrer">Deblx Developer Discord</a>.</p><h2 id="why-verification" tabindex="-1">Why Verification? <a class="header-anchor" href="#why-verification" aria-label="Permalink to &quot;Why Verification?&quot;">​</a></h2><p>Verification allows moderators to confirm purchases for areas intended for product owners.</p><h2 id="how-to-verify" tabindex="-1">How to Verify <a class="header-anchor" href="#how-to-verify" aria-label="Permalink to &quot;How to Verify&quot;">​</a></h2><ol><li>Join the <a href="https://discord-dev.deblx.com" target="_blank" rel="noreferrer">Deblx Developer Discord</a>.</li><li>Read the server rules and find the current verification instructions.</li><li>Use the <strong>private verification method</strong> provided by the server moderators.</li><li>Submit only the information requested by that process.</li></ol><div class="warning custom-block"><p class="custom-block-title">Protect your purchase information</p><p>Do not post transaction IDs, receipts, passwords, payment details or private account information in a public Discord channel or GitHub issue. Use the current private verification method or contact support.</p></div><h2 id="information-you-may-need" tabindex="-1">Information You May Need <a class="header-anchor" href="#information-you-may-need" aria-label="Permalink to &quot;Information You May Need&quot;">​</a></h2><p>Depending on the product and verification process, you may need the product name, marketplace account name and a transaction reference. Only provide transaction references privately if explicitly requested through the verified process.</p><h2 id="after-verification" tabindex="-1">After Verification <a class="header-anchor" href="#after-verification" aria-label="Permalink to &quot;After Verification&quot;">​</a></h2><p>If the purchase is accepted, moderators can assign the applicable product role or permissions. Available channels and support options depend on the current server configuration.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><h3 id="i-cannot-find-my-transaction-reference" tabindex="-1">I cannot find my transaction reference <a class="header-anchor" href="#i-cannot-find-my-transaction-reference" aria-label="Permalink to &quot;I cannot find my transaction reference&quot;">​</a></h3><p>Check your Fab purchase confirmation or purchase history. Contact Fab support if necessary.</p><h3 id="my-verification-has-not-been-accepted" tabindex="-1">My verification has not been accepted <a class="header-anchor" href="#my-verification-has-not-been-accepted" aria-label="Permalink to &quot;My verification has not been accepted&quot;">​</a></h3><p>Review the current server instructions. If you still need help, contact <a href="/support">Deblx Support</a>.</p><h3 id="i-own-several-deblx-plugins" tabindex="-1">I own several Deblx plugins <a class="header-anchor" href="#i-own-several-deblx-plugins" aria-label="Permalink to &quot;I own several Deblx plugins&quot;">​</a></h3><p>Check the verification requirements for each product. The requirements may differ.</p><h2 id="privacy" tabindex="-1">Privacy <a class="header-anchor" href="#privacy" aria-label="Permalink to &quot;Privacy&quot;">​</a></h2><p>Send only necessary information through a verified private method. For questions about handling personal data, use the <a href="https://deblx.com/help" target="_blank" rel="noreferrer">Deblx Help Center</a>.</p><h2 id="related-resources" tabindex="-1">Related Resources <a class="header-anchor" href="#related-resources" aria-label="Permalink to &quot;Related Resources&quot;">​</a></h2><ul><li><a href="/support">Support &amp; Feedback</a></li><li><a href="/getting-started">Plugin Documentation</a></li></ul>',22)])])}const u=r(o,[["render",n]]);export{f as __pageData,u as default};
